package project.init.framework.authen;import jakarta.servlet.http.HttpServletRequest;import jakarta.servlet.http.HttpServletResponse;import org.springframework.http.HttpStatus;import org.springframework.security.access.AccessDeniedException;import org.springframework.security.web.access.AccessDeniedHandler;import org.springframework.stereotype.Component;import project.init.framework.utils.Constants;import java.io.IOException;@Componentpublic class CustomAccessDeniedHandler implements AccessDeniedHandler {    @Override    public void handle(HttpServletRequest request,                       HttpServletResponse response,                       AccessDeniedException accessDeniedException) throws IOException {        response.setContentType(Constants.APPLICATION_JSON);        response.setStatus(HttpServletResponse.SC_FORBIDDEN);        response.getWriter().write(HttpStatus.FORBIDDEN.getReasonPhrase());    }}